export interface Movie {
  id: number;
  title: string;
  genre: string;
  runtimeMinutes: number;
  format: 'PL dubbing' | 'PL subtitles';
}

export interface Screening {
  id: number;
  movieId: number;
  date: string;
  time: string;
  occupiedSeats: string[];
}

export interface ReservationCustomer {
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
}

export interface Reservation {
  id: number;
  screeningId: number;
  seats: string[];
  customer: ReservationCustomer;
  totalPrice: number;
}

export interface CreateReservationRequest {
  screeningId: number;
  seats: string[];
  customer: ReservationCustomer;
  totalPrice: number;
}

import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { CreateReservationRequest, Movie, Reservation, Screening } from './models';

const BASE_URL = 'http://localhost:3000';

@Injectable({ providedIn: 'root' })
export class ApiService {
  private readonly http = inject(HttpClient);

  getMovies(): Observable<Movie[]> {
    return this.http.get<Movie[]>(`${BASE_URL}/movies`);
  }

  getMovie(id: number): Observable<Movie> {
    return this.http.get<Movie>(`${BASE_URL}/movies/${id}`);
  }

  getScreenings(date: string): Observable<Screening[]> {
    return this.http.get<Screening[]>(`${BASE_URL}/screenings`, { params: { date } });
  }

  getScreening(id: number): Observable<Screening> {
    return this.http.get<Screening>(`${BASE_URL}/screenings/${id}`);
  }

  createReservation(request: CreateReservationRequest): Observable<Reservation> {
    return this.http.post<Reservation>(`${BASE_URL}/reservations`, request);
  }
}

const WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const MONTHS_SHORT = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

function pad(n: number): string {
  return n.toString().padStart(2, '0');
}

export function toIsoDate(date: Date): string {
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}

export function startOfDay(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

export function today(): Date {
  return startOfDay(new Date());
}

export function addDays(date: Date, days: number): Date {
  const result = new Date(date);
  result.setDate(result.getDate() + days);
  return result;
}

/** Parses a strict `YYYY-MM-DD` string, returning null for anything else, including invalid calendar dates. */
export function parseIsoDate(value: string): Date | null {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (!match) return null;
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const date = new Date(year, month - 1, day);
  if (date.getFullYear() !== year || date.getMonth() !== month - 1 || date.getDate() !== day) {
    return null;
  }
  return date;
}

export function isBeforeToday(date: Date): boolean {
  return startOfDay(date).getTime() < today().getTime();
}

export function weekdayName(date: Date): string {
  return WEEKDAYS[date.getDay()];
}

/** Formats as `<Weekday> <D> <Mon> <HH:mm>`, e.g. `Tuesday 15 Sep 16:00`. */
export function formatShowDate(isoDate: string, time: string): string {
  const date = parseIsoDate(isoDate);
  if (!date) return `${isoDate} ${time}`;
  return `${weekdayName(date)} ${date.getDate()} ${MONTHS_SHORT[date.getMonth()]} ${time}`;
}

/** Resolves a raw `date` query param to a selected day: missing, invalid or past dates fall back to today. */
export function resolveSelectedDate(raw: string | null): Date {
  if (!raw) return today();
  const parsed = parseIsoDate(raw);
  if (!parsed || isBeforeToday(parsed)) return today();
  return parsed;
}

export type SeatState = 'available' | 'selected' | 'unavailable' | 'accessible';

export interface SeatCell {
  kind: 'seat';
  row: number;
  column: number;
}

export interface CouchCell {
  kind: 'couch';
  row: number;
  columnStart: number;
  columnEnd: number;
}

export interface GapCell {
  kind: 'aisle' | 'empty';
}

export type RowCell = SeatCell | CouchCell | GapCell;

export const TOTAL_ROWS = 15;
export const COUCH_ROW = 15;

export function seatId(row: number, column: number): string {
  return `R${row}C${column}`;
}

export function couchIds(row: number, columnStart: number, columnEnd: number): [string, string] {
  return [seatId(row, columnStart), seatId(row, columnEnd)];
}

export function parseSeatId(id: string): { row: number; column: number } {
  const match = /^R(\d+)C(\d+)$/.exec(id);
  if (!match) throw new Error(`Invalid seat id: ${id}`);
  return { row: Number(match[1]), column: Number(match[2]) };
}

export function isAccessibleSeat(row: number, column: number): boolean {
  return row === 1 && column >= 10 && column <= 15;
}

export function priceForRow(row: number): number {
  if (row <= 5) return 25;
  if (row <= 10) return 32;
  if (row <= 14) return 39;
  throw new Error(`No single-seat price for row ${row}`);
}

export const COUCH_PRICE = 89;

export function formatPrice(amount: number): string {
  return `${amount.toFixed(2)} PLN`;
}

/** Builds the 24-column-wide row definition (as grid cells, including aisles and the entrance gap). */
export function buildRow(row: number): RowCell[] {
  const cells: RowCell[] = [];

  if (row === COUCH_ROW) {
    cells.push({ kind: 'couch', row, columnStart: 1, columnEnd: 2 });
    cells.push({ kind: 'couch', row, columnStart: 3, columnEnd: 4 });
  } else if (row >= 11) {
    for (let c = 1; c <= 4; c++) cells.push({ kind: 'seat', row, column: c });
  } else {
    for (let c = 1; c <= 4; c++) cells.push({ kind: 'empty' });
  }

  cells.push({ kind: 'aisle' });

  if (row === COUCH_ROW) {
    for (let c = 5; c <= 19; c += 2) cells.push({ kind: 'couch', row, columnStart: c, columnEnd: c + 1 });
  } else {
    for (let c = 5; c <= 20; c++) cells.push({ kind: 'seat', row, column: c });
  }

  cells.push({ kind: 'aisle' });

  if (row === COUCH_ROW) {
    cells.push({ kind: 'couch', row, columnStart: 21, columnEnd: 22 });
    cells.push({ kind: 'couch', row, columnStart: 23, columnEnd: 24 });
  } else {
    for (let c = 21; c <= 24; c++) cells.push({ kind: 'seat', row, column: c });
  }

  return cells;
}

export interface SeatUnit {
  row: number;
  type: 'seat' | 'couch';
  column?: number;
  columnStart?: number;
  columnEnd?: number;
  price: number;
}

/** Groups a flat list of seat identifiers (as stored in the booking) into priced seat/couch units, ordered by row then column. */
export function toSeatUnits(seatIds: string[]): SeatUnit[] {
  const columnsByRow = new Map<number, number[]>();
  for (const id of seatIds) {
    const { row, column } = parseSeatId(id);
    const columns = columnsByRow.get(row) ?? [];
    columns.push(column);
    columnsByRow.set(row, columns);
  }

  const units: SeatUnit[] = [];
  for (const [row, columns] of columnsByRow) {
    columns.sort((a, b) => a - b);
    if (row === COUCH_ROW) {
      for (let i = 0; i < columns.length; i += 2) {
        units.push({ row, type: 'couch', columnStart: columns[i], columnEnd: columns[i + 1], price: COUCH_PRICE });
      }
    } else {
      for (const column of columns) {
        units.push({ row, type: 'seat', column, price: priceForRow(row) });
      }
    }
  }

  units.sort((a, b) => a.row - b.row || unitColumn(a) - unitColumn(b));
  return units;
}

function unitColumn(unit: SeatUnit): number {
  return unit.type === 'couch' ? (unit.columnStart as number) : (unit.column as number);
}

export function seatUnitLabel(unit: SeatUnit): string {
  return unit.type === 'couch' ? `${unit.columnStart}-${unit.columnEnd}` : `${unit.column}`;
}

export function totalPrice(seatIds: string[]): number {
  return toSeatUnits(seatIds).reduce((sum, unit) => sum + unit.price, 0);
}

import { Component, inject } from '@angular/core';
import { MAT_SNACK_BAR_DATA } from '@angular/material/snack-bar';

@Component({
  selector: 'app-toast',
  template: `<span data-testid="toast">{{ message }}</span>`,
})
export class ToastComponent {
  protected readonly message = inject<string>(MAT_SNACK_BAR_DATA);
}

import { Injectable, inject } from '@angular/core';
import { MatSnackBar } from '@angular/material/snack-bar';
import { ToastComponent } from '../shared/toast/toast.component';

@Injectable({ providedIn: 'root' })
export class ToastService {
  private readonly snackBar = inject(MatSnackBar);

  show(message: string): void {
    this.snackBar.openFromComponent(ToastComponent, {
      data: message,
      duration: 4000,
    });
  }
}

import { Injectable, inject, signal } from '@angular/core';
import { SeatUnit, couchIds, seatUnitLabel } from './seat.util';
import { ToastService } from './toast.service';

export interface CheckoutFormValues {
  firstName: string;
  lastName: string;
  email: string;
  confirmEmail: string;
  phone: string;
  termsAccepted: boolean;
}

export interface BookingState {
  screeningId: number;
  seats: string[];
  form: CheckoutFormValues;
  paid: boolean;
  email: string | null;
}

const STORAGE_KEY = 'cinescope.booking';
const MAX_SEATS = 10;

export const EMPTY_FORM: CheckoutFormValues = {
  firstName: '',
  lastName: '',
  email: '',
  confirmEmail: '',
  phone: '',
  termsAccepted: false,
};

function emptyBooking(screeningId: number): BookingState {
  return { screeningId, seats: [], form: { ...EMPTY_FORM }, paid: false, email: null };
}

@Injectable({ providedIn: 'root' })
export class BookingService {
  private readonly toast = inject(ToastService);

  private readonly state = signal<BookingState | null>(loadFromStorage());
  readonly booking = this.state.asReadonly();

  /** Keeps the booking in progress for this screening, or starts a fresh one otherwise. */
  ensureBookingFor(screeningId: number): void {
    const current = this.state();
    if (!current || current.paid || current.screeningId !== screeningId) {
      this.persist(emptyBooking(screeningId));
    }
  }

  isValidFor(screeningId: number): boolean {
    const booking = this.state();
    return !!booking && !booking.paid && booking.screeningId === screeningId && booking.seats.length > 0;
  }

  isPaid(): boolean {
    return this.state()?.paid === true;
  }

  clear(): void {
    this.persist(null);
  }

  toggleSeat(id: string): void {
    const booking = this.state();
    if (!booking) return;
    if (booking.seats.includes(id)) {
      this.setSeats(booking.seats.filter((s) => s !== id));
      return;
    }
    if (!this.canAdd(booking.seats.length, 1)) return;
    this.setSeats([...booking.seats, id]);
  }

  toggleCouch(row: number, columnStart: number, columnEnd: number): void {
    const booking = this.state();
    if (!booking) return;
    const [idA, idB] = couchIds(row, columnStart, columnEnd);
    if (booking.seats.includes(idA) || booking.seats.includes(idB)) {
      this.setSeats(booking.seats.filter((s) => s !== idA && s !== idB));
      return;
    }
    if (!this.canAdd(booking.seats.length, 2)) return;
    this.setSeats([...booking.seats, idA, idB]);
  }

  removeUnit(unit: SeatUnit): void {
    const booking = this.state();
    if (!booking) return;
    if (unit.type === 'couch') {
      const [idA, idB] = couchIds(unit.row, unit.columnStart as number, unit.columnEnd as number);
      this.setSeats(booking.seats.filter((s) => s !== idA && s !== idB));
    } else {
      const label = seatUnitLabel(unit);
      this.setSeats(booking.seats.filter((s) => s !== `R${unit.row}C${label}`));
    }
  }

  updateForm(partial: Partial<CheckoutFormValues>): void {
    const booking = this.state();
    if (!booking) return;
    this.persist({ ...booking, form: { ...booking.form, ...partial } });
  }

  markPaid(email: string): void {
    const booking = this.state();
    if (!booking) return;
    this.persist({ ...booking, paid: true, email });
  }

  private canAdd(currentCount: number, add: number): boolean {
    if (currentCount + add > MAX_SEATS) {
      this.toast.show('Maximum 10 seats per booking');
      return false;
    }
    return true;
  }

  private setSeats(seats: string[]): void {
    const booking = this.state();
    if (!booking) return;
    this.persist({ ...booking, seats });
  }

  private persist(state: BookingState | null): void {
    this.state.set(state);
    if (state) {
      sessionStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    } else {
      sessionStorage.removeItem(STORAGE_KEY);
    }
  }
}

function loadFromStorage(): BookingState | null {
  const raw = sessionStorage.getItem(STORAGE_KEY);
  if (!raw) return null;
  try {
    return JSON.parse(raw) as BookingState;
  } catch {
    return null;
  }
}

