import { inject } from '@angular/core';
import { ResolveFn, Router } from '@angular/router';
import { EMPTY, catchError, map, switchMap } from 'rxjs';
import { ApiService } from './api.service';
import { Movie, Screening } from './models';

export interface ScreeningWithMovie {
  screening: Screening;
  movie: Movie;
}

/** Loads the screening and its movie; redirects to `/` when either request fails. */
export const screeningResolver: ResolveFn<ScreeningWithMovie> = (route) => {
  const api = inject(ApiService);
  const router = inject(Router);
  const id = Number(route.paramMap.get('id'));

  return api.getScreening(id).pipe(
    switchMap((screening) => api.getMovie(screening.movieId).pipe(map((movie) => ({ screening, movie })))),
    catchError(() => {
      router.navigateByUrl('/');
      return EMPTY;
    }),
  );
};

import { inject } from '@angular/core';
import { CanActivateFn, Router } from '@angular/router';
import { BookingService } from './booking.service';

/** Allows routes 3 and 4 only when the booking in progress belongs to this screening and has seats. */
export const bookingInProgressGuard: CanActivateFn = (route) => {
  const bookingService = inject(BookingService);
  const router = inject(Router);
  const id = Number(route.paramMap.get('id'));

  if (bookingService.isValidFor(id)) return true;
  return router.parseUrl('/');
};

/** Allows the confirmation route only once the booking has been paid. */
export const paidBookingGuard: CanActivateFn = () => {
  const bookingService = inject(BookingService);
  const router = inject(Router);

  if (bookingService.isPaid()) return true;
  return router.parseUrl('/');
};

import { Movie, Screening } from '../../core/models';

export interface ScreeningVm {
  id: number;
  time: string;
}

export interface MovieCardVm {
  movie: Movie;
  screenings: ScreeningVm[];
}

export function buildMovieCards(movies: Movie[], screenings: Screening[]): MovieCardVm[] {
  const screeningsByMovie = new Map<number, Screening[]>();
  for (const screening of screenings) {
    const list = screeningsByMovie.get(screening.movieId) ?? [];
    list.push(screening);
    screeningsByMovie.set(screening.movieId, list);
  }

  const cards: MovieCardVm[] = [];
  for (const movie of movies) {
    const movieScreenings = screeningsByMovie.get(movie.id);
    if (!movieScreenings || movieScreenings.length === 0) continue;
    const sorted = [...movieScreenings].sort((a, b) => a.time.localeCompare(b.time));
    cards.push({ movie, screenings: sorted.map((s) => ({ id: s.id, time: s.time })) });
  }
  return cards;
}

import { Component, computed, inject } from '@angular/core';
import { toObservable, toSignal } from '@angular/core/rxjs-interop';
import { MatButtonModule } from '@angular/material/button';
import { MatDatepickerModule } from '@angular/material/datepicker';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { ActivatedRoute, Router } from '@angular/router';
import { Subject, catchError, combineLatest, forkJoin, map, of, startWith, switchMap } from 'rxjs';
import { ApiService } from '../../core/api.service';
import { addDays, resolveSelectedDate, toIsoDate, today, weekdayName } from '../../core/date.util';
import { MovieCardVm, buildMovieCards } from './movie-list.vm';

interface DayButtonVm {
  iso: string;
  label: string;
}

type MoviesResult = { status: 'loading' } | { status: 'error' } | { status: 'loaded'; cards: MovieCardVm[] };

@Component({
  selector: 'app-movie-list',
  imports: [MatButtonModule, MatDatepickerModule, MatFormFieldModule, MatInputModule],
  templateUrl: './movie-list.component.html',
  styleUrl: './movie-list.component.scss',
})
export class MovieListComponent {
  private readonly route = inject(ActivatedRoute);
  private readonly router = inject(Router);
  private readonly api = inject(ApiService);

  private readonly retry$ = new Subject<void>();

  readonly minDate = today();

  readonly dayButtons: DayButtonVm[] = Array.from({ length: 5 }, (_, i) => {
    const date = addDays(today(), i);
    return { iso: toIsoDate(date), label: i === 0 ? 'Today' : weekdayName(date) };
  });

  private readonly queryParamMap = toSignal(this.route.queryParamMap, {
    initialValue: this.route.snapshot.queryParamMap,
  });

  readonly selectedDate = computed(() => resolveSelectedDate(this.queryParamMap().get('date')));
  readonly selectedIso = computed(() => toIsoDate(this.selectedDate()));

  private readonly result = toSignal(
    combineLatest([toObservable(this.selectedIso), this.retry$.pipe(startWith(undefined))]).pipe(
      switchMap(([date]) => this.loadMovies(date)),
    ),
    { initialValue: { status: 'loading' } as MoviesResult },
  );

  readonly isLoading = computed(() => this.result().status === 'loading');
  readonly isError = computed(() => this.result().status === 'error');
  readonly cards = computed(() => {
    const result = this.result();
    return result.status === 'loaded' ? result.cards : [];
  });
  readonly isEmpty = computed(() => this.result().status === 'loaded' && this.cards().length === 0);

  private loadMovies(date: string) {
    return forkJoin({
      movies: this.api.getMovies(),
      screenings: this.api.getScreenings(date),
    }).pipe(
      map(({ movies, screenings }) => ({ status: 'loaded', cards: buildMovieCards(movies, screenings) }) as const),
      startWith({ status: 'loading' } as const),
      catchError(() => of({ status: 'error' } as const)),
    );
  }

  isSelected(iso: string): boolean {
    return this.selectedIso() === iso;
  }

  selectDate(iso: string): void {
    this.router.navigate(['/'], { queryParams: { date: iso } });
  }

  onDatePicked(date: Date | null): void {
    if (!date) return;
    this.selectDate(toIsoDate(date));
  }

  retry(): void {
    this.retry$.next();
  }

  openScreening(screeningId: number): void {
    this.router.navigate(['/screenings', screeningId, 'seats']);
  }
}

:host {
  display: block;
  max-width: 960px;
  margin: 0 auto;
  padding: 24px;
}

.day-picker {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 24px;
}

.movie-list {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.movie-card {
  border: 1px solid #ddd;
  border-radius: 8px;
  padding: 16px;
}

.screenings {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: 8px;
}

import { Route } from '@angular/router';
import { bookingInProgressGuard, paidBookingGuard } from './core/booking.guard';
import { screeningResolver } from './core/screening-resolver';

export const appRoutes: Route[] = [
  {
    path: '',
    loadComponent: () => import('./features/movie-list/movie-list.component').then((m) => m.MovieListComponent),
  },
  {
    path: 'screenings/:id/seats',
    loadComponent: () => import('./features/seat-map/seat-map.component').then((m) => m.SeatMapComponent),
    resolve: { data: screeningResolver },
  },
  {
    path: 'screenings/:id/summary',
    loadComponent: () => import('./features/summary/summary.component').then((m) => m.SummaryComponent),
    canActivate: [bookingInProgressGuard],
    resolve: { data: screeningResolver },
  },
  {
    path: 'screenings/:id/checkout',
    loadComponent: () => import('./features/checkout/checkout.component').then((m) => m.CheckoutComponent),
    canActivate: [bookingInProgressGuard],
    resolve: { data: screeningResolver },
  },
  {
    path: 'confirmation',
    loadComponent: () =>
      import('./features/confirmation/confirmation.component').then((m) => m.ConfirmationComponent),
    canActivate: [paidBookingGuard],
  },
  { path: '**', redirectTo: '' },
];

import { Component, computed, inject } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { MatButtonModule } from '@angular/material/button';
import { ActivatedRoute, Router } from '@angular/router';
import { BookingService } from '../../core/booking.service';
import { formatShowDate } from '../../core/date.util';
import { ScreeningWithMovie } from '../../core/screening-resolver';
import { RowCell, SeatState, isAccessibleSeat, seatId, seatUnitLabel, toSeatUnits } from '../../core/seat.util';
import { buildSeatMapRows } from './seat-map.vm';

const COLORS: Record<SeatState, string> = {
  available: '#2E7D32',
  selected: '#F9A825',
  unavailable: '#C62828',
  accessible: '#1565C0',
};

const LEGEND_ITEMS: { state: SeatState; label: string }[] = [
  { state: 'available', label: 'Available' },
  { state: 'selected', label: 'Selected' },
  { state: 'unavailable', label: 'Unavailable' },
  { state: 'accessible', label: 'Accessible' },
];

@Component({
  selector: 'app-seat-map',
  imports: [MatButtonModule],
  templateUrl: './seat-map.component.html',
  styleUrl: './seat-map.component.scss',
})
export class SeatMapComponent {
  private readonly route = inject(ActivatedRoute);
  private readonly router = inject(Router);
  private readonly bookingService = inject(BookingService);

  readonly legendItems = LEGEND_ITEMS;
  readonly rows = buildSeatMapRows();

  private readonly data = toSignal(this.route.data, { initialValue: this.route.snapshot.data }) as () => {
    data: ScreeningWithMovie;
  };

  readonly screening = computed(() => this.data().data.screening);
  readonly movie = computed(() => this.data().data.movie);
  readonly subtitle = computed(() => `Show Date: ${formatShowDate(this.screening().date, this.screening().time)}`);

  private readonly occupiedSet = computed(() => new Set(this.screening().occupiedSeats));
  private readonly booking = this.bookingService.booking;
  private readonly selectedSet = computed(() => new Set(this.booking()?.seats ?? []));

  readonly selectedCount = computed(() => this.booking()?.seats.length ?? 0);
  readonly selectedByRow = computed(() => {
    const units = toSeatUnits(this.booking()?.seats ?? []);
    const rows: { row: number; seats: string }[] = [];
    for (const unit of units) {
      const label = seatUnitLabel(unit);
      const last = rows[rows.length - 1];
      if (last && last.row === unit.row) {
        last.seats = `${last.seats}, ${label}`;
      } else {
        rows.push({ row: unit.row, seats: label });
      }
    }
    return rows;
  });

  constructor() {
    const id = Number(this.route.snapshot.paramMap.get('id'));
    this.bookingService.ensureBookingFor(id);
  }

  seatState(row: number, column: number): SeatState {
    const id = seatId(row, column);
    if (this.occupiedSet().has(id)) return 'unavailable';
    if (this.selectedSet().has(id)) return 'selected';
    if (isAccessibleSeat(row, column)) return 'accessible';
    return 'available';
  }

  couchState(row: number, columnStart: number, columnEnd: number): SeatState {
    const idA = seatId(row, columnStart);
    const idB = seatId(row, columnEnd);
    if (this.occupiedSet().has(idA) || this.occupiedSet().has(idB)) return 'unavailable';
    if (this.selectedSet().has(idA) || this.selectedSet().has(idB)) return 'selected';
    return 'available';
  }

  colorFor(state: SeatState): string {
    return COLORS[state];
  }

  onSeatClick(row: number, column: number): void {
    if (this.seatState(row, column) === 'unavailable') return;
    this.bookingService.toggleSeat(seatId(row, column));
  }

  onCouchClick(row: number, columnStart: number, columnEnd: number): void {
    if (this.couchState(row, columnStart, columnEnd) === 'unavailable') return;
    this.bookingService.toggleCouch(row, columnStart, columnEnd);
  }

  cellKind(cell: RowCell): RowCell['kind'] {
    return cell.kind;
  }

  cancel(): void {
    this.bookingService.clear();
    this.router.navigate(['/']);
  }

  continue(): void {
    if (this.selectedCount() === 0) return;
    this.router.navigate(['/screenings', this.screening().id, 'summary']);
  }
}

