import { CheckoutFormValues } from '../../core/booking.service';

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const PHONE_RE = /^\d{9}$/;

export type CheckoutErrors = Partial<Record<keyof CheckoutFormValues, string>>;

export function computeCheckoutErrors(values: CheckoutFormValues): CheckoutErrors {
  const errors: CheckoutErrors = {};

  if (values.firstName.length === 0) errors.firstName = 'First name is required';
  else if (values.firstName.length < 2) errors.firstName = 'First name must be at least 2 characters';

  if (values.lastName.length === 0) errors.lastName = 'Last name is required';
  else if (values.lastName.length < 2) errors.lastName = 'Last name must be at least 2 characters';

  if (values.email.length === 0) errors.email = 'Email is required';
  else if (!EMAIL_RE.test(values.email)) errors.email = 'Enter a valid email address';

  if (values.confirmEmail.length === 0) errors.confirmEmail = 'Confirm email is required';
  else if (values.confirmEmail !== values.email) errors.confirmEmail = 'Email addresses do not match';

  if (values.phone.length > 0 && !PHONE_RE.test(values.phone)) {
    errors.phone = 'Phone number must be exactly 9 digits';
  }

  if (!values.termsAccepted) errors.termsAccepted = 'You must accept the terms and conditions';

  return errors;
}

import { Component, computed, inject, signal } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { MatButtonModule } from '@angular/material/button';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { ActivatedRoute, Router } from '@angular/router';
import { ApiService } from '../../core/api.service';
import { BookingService, CheckoutFormValues, EMPTY_FORM } from '../../core/booking.service';
import { ScreeningWithMovie } from '../../core/screening-resolver';
import { couchIds, formatPrice, seatId, toSeatUnits, totalPrice } from '../../core/seat.util';
import { ToastService } from '../../core/toast.service';
import { computeCheckoutErrors } from './checkout.validation';

type TouchedState = Record<keyof CheckoutFormValues, boolean>;

const NOT_TOUCHED: TouchedState = {
  firstName: false,
  lastName: false,
  email: false,
  confirmEmail: false,
  phone: false,
  termsAccepted: false,
};

const ALL_TOUCHED: TouchedState = {
  firstName: true,
  lastName: true,
  email: true,
  confirmEmail: true,
  phone: true,
  termsAccepted: true,
};

@Component({
  selector: 'app-checkout',
  imports: [MatButtonModule, MatCheckboxModule, MatFormFieldModule, MatInputModule],
  templateUrl: './checkout.component.html',
  styleUrl: './checkout.component.scss',
})
export class CheckoutComponent {
  private readonly route = inject(ActivatedRoute);
  private readonly router = inject(Router);
  private readonly bookingService = inject(BookingService);
  private readonly api = inject(ApiService);
  private readonly toast = inject(ToastService);

  private readonly data = toSignal(this.route.data, { initialValue: this.route.snapshot.data }) as () => {
    data: ScreeningWithMovie;
  };

  readonly screening = computed(() => this.data().data.screening);

  private readonly booking = this.bookingService.booking;
  readonly values = computed(() => this.booking()?.form ?? EMPTY_FORM);
  readonly errors = computed(() => computeCheckoutErrors(this.values()));

  readonly touched = signal<TouchedState>(NOT_TOUCHED);
  readonly submitting = signal(false);

  readonly payLabel = computed(() => `Pay ${formatPrice(totalPrice(this.booking()?.seats ?? []))}`);

  fieldError(field: keyof CheckoutFormValues): string | null {
    return this.touched()[field] ? (this.errors()[field] ?? null) : null;
  }

  update<K extends keyof CheckoutFormValues>(field: K, value: CheckoutFormValues[K]): void {
    this.bookingService.updateForm({ [field]: value } as Partial<CheckoutFormValues>);
  }

  markTouched(field: keyof CheckoutFormValues): void {
    this.touched.update((t) => ({ ...t, [field]: true }));
  }

  onTermsChange(checked: boolean): void {
    this.update('termsAccepted', checked);
    this.markTouched('termsAccepted');
  }

  back(): void {
    this.router.navigate(['/screenings', this.screening().id, 'summary']);
  }

  pay(): void {
    const hasErrors = Object.values(this.errors()).some(Boolean);
    if (hasErrors) {
      this.touched.set(ALL_TOUCHED);
      this.toast.show('The form contains errors');
      return;
    }

    this.submitting.set(true);
    const values = this.values();
    const seats = this.booking()?.seats ?? [];
    const total = totalPrice(seats);
    const orderedSeats = toSeatUnits(seats).flatMap((unit) =>
      unit.type === 'couch'
        ? couchIds(unit.row, unit.columnStart as number, unit.columnEnd as number)
        : [seatId(unit.row, unit.column as number)],
    );

    this.api
      .createReservation({
        screeningId: this.screening().id,
        seats: orderedSeats,
        customer: {
          firstName: values.firstName,
          lastName: values.lastName,
          email: values.email,
          phone: values.phone,
        },
        totalPrice: total,
      })
      .subscribe({
        next: () => {
          this.bookingService.markPaid(values.email);
          this.submitting.set(false);
          this.router.navigate(['/confirmation']);
        },
        error: () => {
          this.submitting.set(false);
          this.toast.show('Payment failed. Please try again.');
        },
      });
  }
}

