  private readonly seats = computed(() => this.booking()?.seats ?? []);

  readonly items = computed<SummaryItemVm[]>(() =>
    toSeatUnits(this.seats()).map((unit) => ({
      unit,
      row: unit.row,
      seatLabel: unit.type === 'couch' ? `Couch ${seatUnitLabel(unit)}` : seatUnitLabel(unit),
