     ```ts
     const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
     const PHONE_RE = /^\d{9}$/;
     export type CheckoutErrors = Partial<Record<keyof CheckoutFormValues, string>>;
     export function computeCheckoutErrors(values): CheckoutErrors {
       // firstName/lastName: "<Label> is required" if empty, "<Label> must be at least 2 characters" if <2 chars
       // email: "Email is required" / "Enter a valid email address"
       // confirmEmail: "Confirm email is required" / "Email addresses do not match" (compared against raw email, untrimmed)
       // phone: only checked if non-empty — "Phone number must be exactly 9 digits"
       // termsAccepted: "You must accept the terms and conditions" if falsy
     }
     ```

   - **`apps/cinescope/src/app/features/checkout/checkout.component.ts`** (created, edited to fix type cast) — Manual touched-state tracking (`TouchedState` record, `NOT_TOUCHED`/`ALL_TOUCHED` constants) rather than Angular reactive-forms validators, to match exact spec wording about blur/toggle-based message reveal; `values` computed from `booking()?.form ?? EMPTY_FORM`; `errors` computed via `computeCheckoutErrors(values())` (automatically re-evaluates confirmEmail whenever email changes since both read reactively); `fieldError(field)` gates display on `touched()[field]`; `update(field, value)` persists via `bookingService.updateForm`; `markTouched(field)`; `onTermsChange(checked)` updates + marks touched together; `pay()`:
     ```ts
     pay(): void {
       const hasErrors = Object.values(this.errors()).some(Boolean);
       if (hasErrors) {
         this.touched.set(ALL_TOUCHED);
         this.toast.show('The form contains errors');
         return;
       }
       this.submitting.set(true);
       const values = this.values();
       const seats = this.booking()?.seats ?? [];
       const total = totalPrice(seats);
       const orderedSeats = toSeatUnits(seats).flatMap((unit) =>
         unit.type === 'couch'
           ? couchIds(unit.row, unit.columnStart as number, unit.columnEnd as number)
           : [seatId(unit.row, unit.column as number)],
       );
       this.api.createReservation({
         screeningId: this.screening().id, seats: orderedSeats,
         customer: { firstName: values.firstName, lastName: values.lastName, email: values.email, phone: values.phone },
         totalPrice: total,
       }).subscribe({
         next: () => { this.bookingService.markPaid(values.email); this.submitting.set(false); this.router.navigate(['/confirmation']); },
         error: () => { this.submitting.set(false); this.toast.show('Payment failed. Please try again.'); },
       });
     }
     ```

