import { spawn } from 'node:child_process';

const CHROME = '/opt/ms-playwright/chromium-1234/chrome-linux/chrome';
const PORT = 9222;

function sleep(ms) {
  return new Promise((r) => setTimeout(r, ms));
}

async function waitForEndpoint() {
  for (let i = 0; i < 50; i++) {
    try {
      const res = await fetch(`http://127.0.0.1:${PORT}/json/version`);
      if (res.ok) return;
    } catch {
      // not ready yet
    }
    await sleep(200);
  }
  throw new Error('chrome devtools endpoint never came up');
}

const chrome = spawn(
  CHROME,
  [
    '--headless=new',
    '--no-sandbox',
    '--disable-gpu',
    `--remote-debugging-port=${PORT}`,
    '--remote-allow-origins=*',
    '--window-size=1280,720',
  ],
  { stdio: 'ignore' },
);

await waitForEndpoint();

const createRes = await fetch(`http://127.0.0.1:${PORT}/json/new?http://localhost:4200/`, { method: 'PUT' });
const target = await createRes.json();
const ws = new WebSocket(target.webSocketDebuggerUrl);

await new Promise((resolve, reject) => {
  ws.addEventListener('open', resolve, { once: true });
  ws.addEventListener('error', reject, { once: true });
});

let msgId = 1;
const pending = new Map();
ws.addEventListener('message', (event) => {
  const msg = JSON.parse(event.data);
  if (msg.id && pending.has(msg.id)) {
    pending.get(msg.id)(msg);
    pending.delete(msg.id);
  }
});

function send(method, params = {}) {
  const id = msgId++;
  ws.send(JSON.stringify({ id, method, params }));
  return new Promise((resolve) => pending.set(id, resolve));
}

await send('Runtime.enable');
await send('Page.enable');
await sleep(1000);

const script = `
(async () => {
  const results = {};
  const q = (sel) => document.querySelector(sel);
  const qa = (sel) => Array.from(document.querySelectorAll(sel));
  const wait = (ms) => new Promise((r) => setTimeout(r, ms));
  const waitFor = async (fn, timeout = 6000) => {
    const start = Date.now();
    while (Date.now() - start < timeout) {
      const v = fn();
      if (v) return v;
      await wait(100);
    }
    return null;
  };

  await waitFor(() => q('[data-testid="movie-list"]') || q('[data-testid="movies-empty"]') || q('[data-testid="movies-error"]'));
  results.dayPicker = !!q('[data-testid="day-picker"]');
  results.dayButtons = qa('[data-testid="day-button"]').map((b) => ({
    label: b.textContent.trim(),
    date: b.getAttribute('data-date'),
    selected: b.getAttribute('data-selected'),
  }));
  results.movieCards = qa('[data-testid="movie-card"]').length;
  results.firstCardTitle = q('[data-testid="movie-title"]')?.textContent;
  results.firstCardGenre = q('[data-testid="movie-genre"]')?.textContent;
  results.firstCardRuntime = q('[data-testid="movie-runtime"]')?.textContent;
  results.firstCardFormat = q('[data-testid="movie-format"]')?.textContent;
  results.errorText = q('[data-testid="movies-error"]')?.textContent;
  results.emptyText = q('[data-testid="movies-empty"]')?.textContent;

  const screeningBtn = q('[data-testid="screening-button"]');
  results.hasScreeningButton = !!screeningBtn;
  if (screeningBtn) {
    screeningBtn.click();
    await waitFor(() => location.pathname.includes('/seats'));
    await waitFor(() => q('[data-testid="seat-map"]'));
    await wait(300);
    results.seatMapTitle = q('[data-testid="seat-map-title"]')?.textContent;
    results.subtitle = q('[data-testid="seat-map-subtitle"]')?.textContent;
    results.seatLimitInfo = q('[data-testid="seat-limit-info"]')?.textContent;
    results.seatCount = qa('[data-testid="seat"]').length;
    results.couchCount = qa('[data-testid="couch"]').length;
    results.aisleCount = qa('[data-testid="aisle"]').length;
    results.rowCount = qa('[data-testid="seat-row"]').length;
    results.unavailableCount = qa('[data-testid="seat"][data-state="unavailable"], [data-testid="couch"][data-state="unavailable"]').length;
    results.accessibleCount = qa('[data-testid="seat"][data-state="accessible"]').length;
    results.legendItems = qa('[data-testid="legend-item"]').map((e) => e.getAttribute('data-state'));

    const unavailableSeat = q('[data-testid="seat"][data-state="unavailable"]');
    if (unavailableSeat) {
      unavailableSeat.click();
      await wait(100);
      results.unavailableClickNoop = unavailableSeat.getAttribute('data-state') === 'unavailable';
    }

    const availableSeats = qa('[data-testid="seat"][data-state="available"]').slice(0, 2);
    availableSeats.forEach((s) => s.click());
    const couch = q('[data-testid="couch"][data-state="available"]');
    if (couch) couch.click();
    await wait(200);
    results.selectedCountText = q('[data-testid="selected-seats-count"]')?.textContent;
    results.selectedRows = qa('[data-testid="selected-seats-row"]').map((e) => e.textContent);

    q('[data-testid="continue-button"]').click();
    await waitFor(() => location.pathname.includes('/summary'));
    await wait(200);
    results.summaryTitle = q('[data-testid="summary-title"]')?.textContent;
    results.summaryItems = qa('[data-testid="summary-item"]').length;
    results.summaryTotal = q('[data-testid="summary-total"]')?.textContent;
    results.summarySeatDescs = qa('[data-testid="summary-item-seat"]').map((e) => e.textContent);

    q('[data-testid="confirm-button"]').click();
    await waitFor(() => location.pathname.includes('/checkout'));
    await wait(200);
    results.checkoutTitle = q('[data-testid="checkout-title"]')?.textContent;

    const payBtnEarly = q('[data-testid="pay-button"]');
    payBtnEarly.click();
    await wait(200);
    results.invalidPayBlocked = location.pathname.includes('/checkout');
    results.firstNameErrorOnInvalid = q('[data-testid="first-name-error"]')?.textContent;
    results.termsErrorOnInvalid = q('[data-testid="terms-error"]')?.textContent;

    const setVal = (sel, val) => {
      const el = q(sel);
      const proto = Object.getPrototypeOf(el);
      const setter = Object.getOwnPropertyDescriptor(proto, 'value').set;
      setter.call(el, val);
      el.dispatchEvent(new Event('input', { bubbles: true }));
      el.dispatchEvent(new Event('blur', { bubbles: true }));
    };
    setVal('[data-testid="first-name-input"]', 'Anna');
    setVal('[data-testid="last-name-input"]', 'Kowalska');
    setVal('[data-testid="email-input"]', 'anna@example.com');
    setVal('[data-testid="confirm-email-input"]', 'anna@example.com');
    await wait(100);
    const termsHost = q('[data-testid="terms-checkbox"]');
    (termsHost.querySelector('input') || termsHost).click();
    await wait(200);
    results.payLabel = q('[data-testid="pay-button"]')?.textContent.trim();
    results.firstNameErrorAfterFix = q('[data-testid="first-name-error"]')?.textContent || null;

    q('[data-testid="pay-button"]').click();
    const ok = await waitFor(() => location.pathname.includes('/confirmation'), 8000);
    results.reachedConfirmation = !!ok;
    results.confirmationHeading = q('[data-testid="confirmation-heading"]')?.textContent;
    results.confirmationMessage = q('[data-testid="confirmation-message"]')?.textContent;
  }

  return results;
})()
`;

const evalResult = await send('Runtime.evaluate', {
