     ```ts
     pay(): void {
       const hasErrors = Object.values(this.errors()).some(Boolean);
       if (hasErrors) {
         this.touched.set(ALL_TOUCHED);
         this.toast.show('The form contains errors');
         return;
       }
       this.submitting.set(true);
       const values = this.values();
       const seats = this.booking()?.seats ?? [];
       const total = totalPrice(seats);
       const orderedSeats = toSeatUnits(seats).flatMap((unit) =>
         unit.type === 'couch'
           ? couchIds(unit.row, unit.columnStart as number, unit.columnEnd as number)
           : [seatId(unit.row, unit.column as number)],
       );
       this.api.createReservation({
         screeningId: this.screening().id, seats: orderedSeats,
         customer: { firstName: values.firstName, lastName: values.lastName, email: values.email, phone: values.phone },
         totalPrice: total,
       }).subscribe({
         next: () => { this.bookingService.markPaid(values.email); this.submitting.set(false); this.router.navigate(['/confirmation']); },
         error: () => { this.submitting.set(false); this.toast.show('Payment failed. Please try again.'); },
       });
     }
     ```

